import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import numpy as np
import base64
import io
import re
import os

# ── Configuration ──────────────────────────────────────────────────────
DATA_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'

# Orbit classification thresholds (MEAN_MOTION in rev/day)
LEO_THRESHOLD = 11.25    # > 11.25 rev/day ≈ LEO
GEO_LOW = 0.99           # ~1.0 rev/day ≈ GEO
GEO_HIGH = 1.01
# MEO: between LEO threshold and ~2 rev/day (but not GEO)
# HEO: high eccentricity (> 0.1) with unusual mean motions

COLORS = {
    'leo': '#3B82F6',
    'meo': '#8B5CF6',
    'geo': '#F59E0B',
    'heo': '#EF4444',
    'accent': '#2563EB',
    'accent2': '#10B981',
    'accent3': '#F97316',
    'bg': '#F8FAFC',
    'card_bg': '#FFFFFF',
    'text': '#1E293B',
    'text_secondary': '#64748B',
    'border': '#E2E8F0',
}

# ── Data Loading & Cleaning ────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)

# Convert string columns to numeric
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')
df['MEAN_MOTION'] = pd.to_numeric(df['MEAN_MOTION'], errors='coerce')
df['INCLINATION'] = pd.to_numeric(df['INCLINATION'], errors='coerce')

# Extract launch year from OBJECT_ID (first 4 characters)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Parse EPOCH
df['EPOCH_DT'] = pd.to_datetime(df['EPOCH'], errors='coerce')

# ── Orbit Classification ───────────────────────────────────────────────
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if ecc > 0.1 and mm < 10:
        return 'HEO'
    if GEO_LOW <= mm <= GEO_HIGH:
        return 'GEO'
    if mm > LEO_THRESHOLD:
        return 'LEO'
    if 2.0 <= mm <= LEO_THRESHOLD:
        return 'MEO'
    if 1.01 < mm < 2.0:
        return 'MEO'
    return 'Other'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# ── Constellation Identification ───────────────────────────────────────
def identify_constellation(name):
    name_upper = name.upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    if name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    if name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    if name_upper.startswith('GPS') or 'NAVSTAR' in name_upper:
        return 'GPS'
    if name_upper.startswith('COSMO') or name_upper.startswith('COSMOS-SKY') or name_upper.startswith('COSMOS 2'):
        return 'Cosmo-SkyMed'
    if name_upper.startswith('GLO') or name_upper.startswith('COSMOS') and 'GLONASS' in name_upper:
        return 'GLONASS'
    if name_upper.startswith('GALILEO'):
        return 'Galileo'
    if name_upper.startswith('BEIDOU') or name_upper.startswith('COMPASS') or name_upper.startswith('BEIDOU'):
        return 'BeiDou'
    if 'GLOBALSTAR' in name_upper:
        return 'Globalstar'
    if name_upper.startswith('SWARM') or name_upper.startswith('SPACEBEE'):
        return 'Swarm'
    if name_upper.startswith('FLOCK'):
        return 'Flock (Planet)'
    if name_upper.startswith('SKYSAT'):
        return 'SkySat (Planet)'
    if name_upper.startswith('DOVE'):
        return 'Dove (Planet)'
    if name_upper.startswith('SENTINEL'):
        return 'Sentinel'
    if name_upper.startswith('NOAA') or name_upper.startswith('GOES') or name_upper.startswith('METOP') or name_upper.startswith('METEOSAT'):
        return 'Weather/Env'
    if name_upper.startswith('TDRS'):
        return 'TDRS'
    if name_upper.startswith('KH') or name_upper.startswith('USA') or name_upper.startswith('LACROSSE') or name_upper.startswith('ONYX'):
        return 'US Recon'
    if name_upper.startswith('YAOGAN'):
        return 'Yaogan (ISR)'
    if name_upper.startswith('LIAONING') or name_upper.startswith('TIANHUI') or name_upper.startswith('GAOFEN') or name_upper.startswith('ZIYUAN') or name_upper.startswith('CBERS'):
        return 'Chinese EO'
    if name_upper.startswith('WORLDVIEW') or name_upper.startswith('GEOEYE') or name_upper.startswith('QUICKBIRD') or name_upper.startswith('IKONOS'):
        return 'Commercial EO'
    if name_upper.startswith('INMARSAT'):
        return 'Inmarsat'
    if name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    if name_upper.startswith('SES') or name_upper.startswith('ASTRA'):
        return 'SES'
    if name_upper.startswith('EUTELSAT'):
        return 'Eutelsat'
    if name_upper.startswith('TELESAT') or name_upper.startswith('ANIK'):
        return 'Telesat'
    if name_upper.startswith('AMAZON') or name_upper.startswith('KUIPER'):
        return 'Kuiper'
    if name_upper.startswith('ISS') or name_upper == 'ISS':
        return 'ISS'
    if name_upper.startswith('HST'):
        return 'HST'
    return None

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# ── KPI Computation ────────────────────────────────────────────────────
total_sats = len(df)
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = leo_count / total_sats * 100
starlink_count = len(df[df['OBJECT_NAME'].str.upper().str.startswith('STARLINK')])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])
post_2020_share = post_2020_count / total_sats * 100

orbit_counts = df['ORBIT_REGIME'].value_counts()
meo_count = orbit_counts.get('MEO', 0)
geo_count = orbit_counts.get('GEO', 0)
heo_count = orbit_counts.get('HEO', 0)

epoch_min = df['EPOCH_DT'].min()
epoch_max = df['EPOCH_DT'].max()
oldest_launch = df['LAUNCH_YEAR'].min()
newest_launch = df['LAUNCH_YEAR'].max()
mean_ecc = df['ECCENTRICITY'].mean()
median_mm = df['MEAN_MOTION'].median()

starlink_share = starlink_count / total_sats * 100

# ── Chart Generation Helpers ───────────────────────────────────────────
def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

def style_axis(ax, title, xlabel='', ylabel=''):
    ax.set_title(title, fontsize=13, fontweight='bold', color=COLORS['text'], pad=10)
    if xlabel:
        ax.set_xlabel(xlabel, fontsize=10, color=COLORS['text_secondary'])
    if ylabel:
        ax.set_ylabel(ylabel, fontsize=10, color=COLORS['text_secondary'])
    ax.tick_params(colors=COLORS['text_secondary'], labelsize=9)
    for spine in ax.spines.values():
        spine.set_color(COLORS['border'])
    ax.set_facecolor(COLORS['bg'])

# ── Chart 1: Launch Year Trend ────────────────────────────────────────
launch_by_year = df.groupby('LAUNCH_YEAR').size().reset_index(name='COUNT')
# Cumulative count
launch_by_year['CUMULATIVE'] = launch_by_year['COUNT'].cumsum()

fig, ax1 = plt.subplots(figsize=(12, 5.5))
bars = ax1.bar(launch_by_year['LAUNCH_YEAR'], launch_by_year['COUNT'],
               color=COLORS['accent'], alpha=0.75, width=0.7, label='Annual Launches')
ax2 = ax1.twinx()
ax2.plot(launch_by_year['LAUNCH_YEAR'], launch_by_year['CUMULATIVE'],
         color=COLORS['accent3'], linewidth=2.5, marker='o', markersize=3, label='Cumulative Fleet')

style_axis(ax1, 'Active Satellites by Launch Year', 'Launch Year', 'Satellites Launched (per year)')
ax2.set_ylabel('Cumulative Active Satellites', fontsize=10, color=COLORS['accent3'])
ax2.tick_params(axis='y', colors=COLORS['accent3'], labelsize=9)
ax2.spines['right'].set_color(COLORS['accent3'])

# Annotate the surge
recent = launch_by_year[launch_by_year['LAUNCH_YEAR'] >= 2020]
if len(recent) > 0:
    peak_row = recent.loc[recent['COUNT'].idxmax()]
    ax1.annotate(f'{int(peak_row["COUNT"]):,} sats\n({int(peak_row["LAUNCH_YEAR"])})',
                 xy=(peak_row['LAUNCH_YEAR'], peak_row['COUNT']),
                 xytext=(peak_row['LAUNCH_YEAR'] - 8, peak_row['COUNT'] * 0.85),
                 fontsize=9, fontweight='bold', color=COLORS['text'],
                 arrowprops=dict(arrowstyle='->', color=COLORS['text_secondary'], lw=1.2))

# Lines, legends
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper left', fontsize=9,
           framealpha=0.9, edgecolor=COLORS['border'])

ax1.set_xlim(launch_by_year['LAUNCH_YEAR'].min() - 1, launch_by_year['LAUNCH_YEAR'].max() + 1)
chart_launch_trend = fig_to_base64(fig)

# ── Chart 2: Orbit Regime Distribution ────────────────────────────────
regime_order = ['LEO', 'MEO', 'GEO', 'HEO', 'Other']
regime_colors = [COLORS['leo'], COLORS['meo'], COLORS['geo'], COLORS['heo'], '#94A3B8']
regime_vals = [orbit_counts.get(r, 0) for r in regime_order]
regime_pcts = [v / total_sats * 100 for v in regime_vals]

fig, (ax_pie, ax_bar) = plt.subplots(1, 2, figsize=(12, 5))

wedges, texts, autotexts = ax_pie.pie(
    regime_vals, labels=regime_order, autopct='%1.1f%%',
    colors=regime_colors, startangle=90, pctdistance=0.75,
    textprops={'fontsize': 10, 'color': COLORS['text']})
for at in autotexts:
    at.set_fontweight('bold')
ax_pie.set_title('Orbital Regime Share', fontsize=13, fontweight='bold', color=COLORS['text'], pad=12)

bars = ax_bar.barh(regime_order[::-1], [regime_vals[i] for i in range(len(regime_order)-1, -1, -1)],
                   color=regime_colors[::-1], edgecolor='white', height=0.55)
ax_bar.set_xlabel('Number of Satellites', fontsize=10, color=COLORS['text_secondary'])
style_axis(ax_bar, 'Satellite Count by Regime')
for bar, val in zip(bars, [regime_vals[i] for i in range(len(regime_order)-1, -1, -1)]):
    ax_bar.text(bar.get_width() + max(regime_vals)*0.02, bar.get_y() + bar.get_height()/2,
                f'{val:,}', va='center', fontsize=9, color=COLORS['text_secondary'])
ax_bar.set_xlim(0, max(regime_vals) * 1.15)

plt.tight_layout()
chart_orbit_regime = fig_to_base64(fig)

# ── Chart 3: Constellation Breakdown ──────────────────────────────────
constellation_counts = df.groupby('CONSTELLATION').size().reset_index(name='COUNT')
constellation_counts = constellation_counts.dropna(subset=['CONSTELLATION'])
constellation_counts = constellation_counts.sort_values('COUNT', ascending=False)
top_constellations = constellation_counts.head(15).copy()
other_named = constellation_counts.iloc[15:]
other_count = len(df[df['CONSTELLATION'].isna()]) + other_named['COUNT'].sum()
top_constellations = pd.concat([top_constellations, pd.DataFrame({'CONSTELLATION': ['Other / Unclassified'], 'COUNT': [other_count]})], ignore_index=True)

const_colors = plt.cm.tab20(np.linspace(0, 1, len(top_constellations)))

fig, ax = plt.subplots(figsize=(12, 6))
bars = ax.barh(top_constellations['CONSTELLATION'].values[::-1],
               top_constellations['COUNT'].values[::-1],
               color=const_colors[::-1], edgecolor='white', height=0.65)
style_axis(ax, 'Top Satellite Constellations & Operators', '', 'Number of Active Satellites')
for bar, val in zip(bars, top_constellations['COUNT'].values[::-1]):
    pct = val / total_sats * 100
    ax_bar_text = f'{val:,} ({pct:.1f}%)'
    ax.text(bar.get_width() + max(top_constellations['COUNT'])*0.01,
            bar.get_y() + bar.get_height()/2,
            ax_bar_text, va='center', fontsize=9, color=COLORS['text_secondary'])
ax.set_xlim(0, max(top_constellations['COUNT']) * 1.25)
chart_constellation = fig_to_base64(fig)

# ── Chart 4: Inclination Distribution ─────────────────────────────────
fig, ax = plt.subplots(figsize=(11, 5))
ax.hist(df['INCLINATION'].dropna(), bins=90, color=COLORS['accent'], alpha=0.8, edgecolor='white', linewidth=0.3)
ax.axvline(median_inclination, color=COLORS['accent3'], linewidth=2, linestyle='--',
           label=f'Median: {median_inclination:.1f}°')
style_axis(ax, 'Orbital Inclination Distribution', 'Inclination (degrees)', 'Number of Satellites')
ax.legend(fontsize=10, framealpha=0.9, edgecolor=COLORS['border'])
chart_inclination = fig_to_base64(fig)

# ── Chart 5: Eccentricity Distribution ────────────────────────────────
ecc_data = df['ECCENTRICITY'].dropna()
fig, (ax_ecc1, ax_ecc2) = plt.subplots(1, 2, figsize=(12, 5))

# Left: full distribution (log scale)
ax_ecc1.hist(ecc_data, bins=100, color=COLORS['accent2'], alpha=0.8, edgecolor='white', linewidth=0.3)
ax_ecc1.set_yscale('log')
style_axis(ax_ecc1, 'Eccentricity Distribution (Full)', 'Eccentricity', 'Count (log scale)')

# Right: zoomed to low eccentricity (circular orbits)
ecc_circular = ecc_data[ecc_data < 0.05]
ax_ecc2.hist(ecc_circular, bins=80, color=COLORS['accent2'], alpha=0.8, edgecolor='white', linewidth=0.3)
style_axis(ax_ecc2, 'Eccentricity Distribution (e < 0.05)', 'Eccentricity', 'Count')
pct_circular = len(ecc_circular) / len(ecc_data) * 100
ax_ecc2.text(0.97, 0.95, f'{pct_circular:.1f}% have e < 0.05',
             transform=ax_ecc2.transAxes, fontsize=9, ha='right', va='top',
             bbox=dict(boxstyle='round,pad=0.3', facecolor=COLORS['bg'], edgecolor=COLORS['border']))

plt.tight_layout()
chart_eccentricity = fig_to_base64(fig)

# ── Chart 6: Mean Motion Distribution ─────────────────────────────────
fig, ax = plt.subplots(figsize=(11, 5))
mm_data = df['MEAN_MOTION'].dropna()
ax.hist(mm_data, bins=120, color='#6366F1', alpha=0.8, edgecolor='white', linewidth=0.3)
ax.axvline(LEO_THRESHOLD, color=COLORS['heo'], linewidth=1.5, linestyle='--', label=f'LEO cutoff (> {LEO_THRESHOLD} rev/day)')
ax.axvline(1.0, color=COLORS['geo'], linewidth=1.5, linestyle='--', label='GEO (~1.0 rev/day)')
style_axis(ax, 'Mean Motion Distribution', 'Mean Motion (rev/day)', 'Number of Satellites')
ax.legend(fontsize=9, framealpha=0.9, edgecolor=COLORS['border'])
chart_mean_motion = fig_to_base64(fig)

# ── Chart 7: Starlink vs Non-Starlink by Orbit ────────────────────────
df['IS_STARLINK'] = df['OBJECT_NAME'].str.upper().str.startswith('STARLINK')
regime_sl = df[df['IS_STARLINK']].groupby('ORBIT_REGIME').size()
regime_nonsl = df[~df['IS_STARLINK']].groupby('ORBIT_REGIME').size()

regimes_plot = ['LEO', 'MEO', 'GEO', 'HEO']
sl_vals = [regime_sl.get(r, 0) for r in regimes_plot]
nonsl_vals = [regime_nonsl.get(r, 0) for r in regimes_plot]

fig, ax = plt.subplots(figsize=(10, 5))
x = np.arange(len(regimes_plot))
w = 0.35
ax.bar(x - w/2, sl_vals, w, label='Starlink', color=COLORS['accent'], alpha=0.85)
ax.bar(x + w/2, nonsl_vals, w, label='Non-Starlink', color=COLORS['accent2'], alpha=0.85)
ax.set_xticks(x)
ax.set_xticklabels(regimes_plot)
style_axis(ax, 'Starlink vs. Non-Starlink by Orbital Regime', 'Orbital Regime', 'Number of Satellites')
ax.legend(fontsize=10, framealpha=0.9, edgecolor=COLORS['border'])
chart_starlink_regime = fig_to_base64(fig)

# ── Chart 8: Launch Year Trend — Starlink vs Others ───────────────────
sl_year = df[df['IS_STARLINK']].groupby('LAUNCH_YEAR').size().reset_index(name='SL')
other_year = df[~df['IS_STARLINK']].groupby('LAUNCH_YEAR').size().reset_index(name='OTHER')
trend_df = pd.merge(sl_year, other_year, on='LAUNCH_YEAR', how='outer').fillna(0)
trend_df = trend_df.sort_values('LAUNCH_YEAR')

fig, ax = plt.subplots(figsize=(12, 5.5))
ax.bar(trend_df['LAUNCH_YEAR'], trend_df['SL'], color=COLORS['accent'], alpha=0.8, label='Starlink', width=0.7)
ax.bar(trend_df['LAUNCH_YEAR'], trend_df['OTHER'], bottom=trend_df['SL'],
       color=COLORS['accent2'], alpha=0.8, label='Non-Starlink', width=0.7)
style_axis(ax, 'Annual Launches: Starlink vs. All Other Satellites', 'Launch Year', 'Satellites Launched')
