# ── Orbit Classification ───────────────────────────────────────────────
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if ecc > 0.1 and mm < 10:
        return 'HEO'
    if GEO_LOW <= mm <= GEO_HIGH:
        return 'GEO'
    if mm > LEO_THRESHOLD:
        return 'LEO'
    if 2.0 <= mm <= LEO_THRESHOLD:
        return 'MEO'
    if 1.01 < mm < 2.0:
        return 'MEO'
    return 'Other'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# ── Constellation Identification ───────────────────────────────────────
def identify_constellation(name):
    name_upper = name.upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    if name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    if name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    if name_upper.startswith('GPS') or 'NAVSTAR' in name_upper:
        return 'GPS'
    if name_upper.startswith('COSMO') or name_upper.startswith('COSMOS-SKY') or name_upper.startswith('COSMOS 2'):
        return 'Cosmo-SkyMed'
    if name_upper.startswith('GLO') or name_upper.startswith('COSMOS') and 'GLONASS' in name_upper:
        return 'GLONASS'
    if name_upper.startswith('GALILEO'):
        return 'Galileo'
    if name_upper.startswith('BEIDOU') or name_upper.startswith('COMPASS') or name_upper.startswith('BEIDOU'):
        return 'BeiDou'
    if 'GLOBALSTAR' in name_upper:
        return 'Globalstar'
    if name_upper.startswith('SWARM') or name_upper.startswith('SPACEBEE'):
        return 'Swarm'
    if name_upper.startswith('FLOCK'):
        return 'Flock (Planet)'
    if name_upper.startswith('SKYSAT'):
        return 'SkySat (Planet)'
    if name_upper.startswith('DOVE'):
        return 'Dove (Planet)'
    if name_upper.startswith('SENTINEL'):
        return 'Sentinel'
    if name_upper.startswith('NOAA') or name_upper.startswith('GOES') or name_upper.startswith('METOP') or name_upper.startswith('METEOSAT'):
        return 'Weather/Env'
    if name_upper.startswith('TDRS'):
        return 'TDRS'
    if name_upper.startswith('KH') or name_upper.startswith('USA') or name_upper.startswith('LACROSSE') or name_upper.startswith('ONYX'):
        return 'US Recon'
    if name_upper.startswith('YAOGAN'):
        return 'Yaogan (ISR)'
    if name_upper.startswith('LIAONING') or name_upper.startswith('TIANHUI') or name_upper.startswith('GAOFEN') or name_upper.startswith('ZIYUAN') or name_upper.startswith('CBERS'):
        return 'Chinese EO'
    if name_upper.startswith('WORLDVIEW') or name_upper.startswith('GEOEYE') or name_upper.startswith('QUICKBIRD') or name_upper.startswith('IKONOS'):
        return 'Commercial EO'
    if name_upper.startswith('INMARSAT'):
        return 'Inmarsat'
    if name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    if name_upper.startswith('SES') or name_upper.startswith('ASTRA'):
        return 'SES'
    if name_upper.startswith('EUTELSAT'):
        return 'Eutelsat'
    if name_upper.startswith('TELESAT') or name_upper.startswith('ANIK'):
        return 'Telesat'
    if name_upper.startswith('AMAZON') or name_upper.startswith('KUIPER'):
        return 'Kuiper'
    if name_upper.startswith('ISS') or name_upper == 'ISS':
        return 'ISS'
    if name_upper.startswith('HST'):
        return 'HST'
    return None

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

