    border-top: 1px solid var(--border); margin-top: 48px;
  }}

  @media (max-width: 768px) {{
    .kpi-strip {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<header>
  <div class="container">
    <h1>Active Satellites in Earth Orbit</h1>
    <div class="subtitle">2026 Catalog Analysis &mdash; Data-Driven Orbital Environment Assessment</div>
    <div class="epoch-range">EPOCH range: {epoch_min.strftime('%Y-%m-%d')} to {epoch_max.strftime('%Y-%m-%d')} &nbsp;|&nbsp; Source: CelesTrak / NORAD TLE</div>
  </div>
</header>

<div class="container">

<!-- ═══════════ KPI STRIP ═══════════ -->
<div class="kpi-strip">
  <div class="kpi-card">
    <div class="metric">{total_sats:,}</div>
    <div class="label">Total Active Satellites</div>
  </div>
  <div class="kpi-card">
    <div class="metric">{leo_share:.1f}%</div>
    <div class="label">LEO Share</div>
  </div>
  <div class="kpi-card">
    <div class="metric">{starlink_count:,}</div>
    <div class="label">Starlink Constellation</div>
  </div>
  <div class="kpi-card">
    <div class="metric">{median_inclination:.1f}°</div>
    <div class="label">Median Inclination</div>
  </div>
  <div class="kpi-card">
    <div class="metric">{post_2020_count:,}</div>
    <div class="label">Launched Since 2020</div>
  </div>
</div>

<!-- ═══════════ SECTION 1: OVERVIEW ═══════════ -->
<section id="overview">
  <h2>Catalog Overview &amp; Key Figures</h2>
  <p>This report analyzes <strong>{total_sats:,}</strong> active satellites tracked in the CelesTrak/NORAD catalog as of {epoch_max.strftime('%B %Y')}. The dataset spans launches from <strong>{oldest_launch}</strong> to <strong>{newest_launch}</strong>, with orbital element sets refreshed between {epoch_min.strftime('%Y-%m-%d')} and {epoch_max.strftime('%Y-%m-%d')}.</p>

  <div class="callout">
    <strong>Post-2020 dominance:</strong> {post_2020_count:,} satellites ({post_2020_share:.1f}% of the active fleet) were launched in 2020 or later, reflecting the rapid deployment of mega-constellations and the acceleration of commercial space activity.
  </div>

  <h3>Summary Statistics</h3>
  <table>
    <tr><th>Statistic</th><th class="num">Value</th></tr>
    <tr><td>Total active satellites</td><td class="num">{total_sats:,}</td></tr>
    <tr><td>EPOCH coverage</td><td class="num">{epoch_min.strftime('%Y-%m-%d')} &mdash; {epoch_max.strftime('%Y-%m-%d')}</td></tr>
    <tr><td>Oldest active satellite (launch year)</td><td class="num">{oldest_launch}</td></tr>
    <tr><td>Newest active satellite (launch year)</td><td class="num">{newest_launch}</td></tr>
    <tr><td>Median mean motion</td><td class="num">{median_mm:.4f} rev/day</td></tr>
    <tr><td>Median inclination</td><td class="num">{median_inclination:.1f}°</td></tr>
    <tr><td>Mean eccentricity</td><td class="num">{mean_ecc:.6f}</td></tr>
    <tr><td>Satellites launched &ge; 2020</td><td class="num">{post_2020_count:,} ({post_2020_share:.1f}%)</td></tr>
  </table>
</section>

<!-- ═══════════ SECTION 2: ORBIT REGIME ═══════════ -->
<section id="orbit-regime">
  <h2>Orbital Regime Classification</h2>
  <p>Satellites are classified into orbital regimes using <strong>MEAN_MOTION</strong> thresholds derived from Kepler's third law and standard orbital mechanics conventions:</p>
  <ul style="margin:8px 0 16px 24px; color:var(--text2); font-size:0.92rem;">
    <li><strong>LEO</strong> (Low Earth Orbit): MEAN_MOTION &gt; {LEO_THRESHOLD} rev/day (&asymp; 160&ndash;2,000 km altitude)</li>
    <li><strong>MEO</strong> (Medium Earth Orbit): 2.0 &le; MEAN_MOTION &le; {LEO_THRESHOLD} rev/day, excluding GEO band</li>
    <li><strong>GEO</strong> (Geostationary Orbit): 0.99 &le; MEAN_MOTION &le; 1.01 rev/day (&asymp; 35,786 km altitude)</li>
    <li><strong>HEO</strong> (Highly Elliptical Orbit): ECCENTRICITY &gt; 0.1 and MEAN_MOTION &lt; 10 rev/day (e.g., Molniya orbits)</li>
  </ul>

  <div class="chart-card">{img_tag(chart_orbit_regime, 'Orbital Regime Distribution')}</div>

  <h3>Regime Detail</h3>
  <table>
    <tr><th>Regime</th><th class="num">Count</th><th class="num">Share (%)</th><th class="num">Median Inc. (°)</th><th class="num">Median Ecc.</th><th class="num">Median MM (rev/d)</th></tr>
'''

for rd in regime_table_data:
    html += f'''    <tr>
      <td><strong>{rd['Regime']}</strong></td>
      <td class="num">{rd['Count']:,}</td>
      <td class="num">{rd['Share (%)']}</td>
      <td class="num">{rd['Median Inc. (°)']}</td>
      <td class="num">{rd['Median Ecc.']:.6f}</td>
      <td class="num">{rd['Median MM (rev/d)']}</td>
    </tr>
'''

html += f'''  </table>

  <div class="callout">
    <strong>LEO concentration:</strong> {leo_count:,} satellites ({leo_share:.1f}%) occupy Low Earth Orbit, overwhelmingly driven by communications mega-constellations. By contrast, GEO holds {geo_count:,} satellites and MEO holds {meo_count:,} (primarily navigation constellations).
  </div>
</section>

<!-- ═══════════ SECTION 3: CONSTELLATION ANALYSIS ═══════════ -->
<section id="constellation-analysis">
  <h2>Major Constellation &amp; Operator Breakdown</h2>
  <p>Constellation membership is determined by parsing <strong>OBJECT_NAME</strong> prefixes. The table below lists the top 10 identified constellations by active satellite count, along with their share of the total catalog.</p>

  <table>
    <tr><th>#</th><th>Constellation / Operator</th><th class="num">Active Satellites</th><th class="num">Share (%)</th><th class="num">Cum. Share (%)</th></tr>
'''

for i, row in top_const_table.iterrows():
    html += f'''    <tr>
      <td>{i+1}</td>
      <td><strong>{row['CONSTELLATION']}</strong></td>
      <td class="num">{int(row['COUNT']):,}</td>
      <td class="num">{row['SHARE']}</td>
      <td class="num">{row['CUM_SHARE']}</td>
    </tr>
'''

html += f'''  </table>

  <div class="chart-card">{img_tag(chart_constellation, 'Top Constellations')}</div>

  <div class="callout warning">
    <strong>Starlink dominance:</strong> SpaceX's Starlink accounts for <strong>{starlink_count:,}</strong> satellites &mdash; <strong>{starlink_share:.1f}%</strong> of all active satellites in orbit. A single commercial operator holds a majority-share position in LEO, reshaping statistical distributions of inclination, mean motion, and launch-trend curves.
  </div>

  <div class="chart-card">{img_tag(chart_starlink_regime, 'Starlink vs Non-Starlink by Regime')}</div>
</section>

<!-- ═══════════ SECTION 4: LAUNCH TRENDS ═══════════ -->
<section id="launch-trends">
  <h2>Launch Year Trends</h2>
  <p>The launch-year distribution of currently active satellites reveals the dramatic acceleration in orbital deployments. The chart below shows both annual launch counts and the cumulative size of the active fleet over time.</p>

  <div class="chart-card">{img_tag(chart_launch_trend, 'Launch Year Trend')}</div>

  <div class="callout">
    <strong>Exponential growth post-2019:</strong> The active fleet has more than tripled since 2019. Annual launch volumes surged from a few dozen per year in the 2000s to thousands per year in the 2020s, driven almost entirely by Starlink and OneWeb deployments.
  </div>

  <h3>Starlink's Contribution to Launch Acceleration</h3>
  <p>Disentangling Starlink from the broader launch trend shows that non-Starlink launches have also increased, but the scale and pace of the constellation buildup is unprecedented.</p>

  <div class="chart-card">{img_tag(chart_starlink_trend, 'Starlink vs Other Launch Trend')}</div>

  <h3>Decadal Summary</h3>
  <table>
    <tr><th>Decade</th><th class="num">Active Satellites Launched</th><th class="num">Share of Fleet (%)</th></tr>
'''

decades = [(1960, 1969), (1970, 1979), (1980, 1989), (1990, 1999), (2000, 2009), (2010, 2019), (2020, 2029)]
for start, end in decades:
    cnt = len(df[(df['LAUNCH_YEAR'] >= start) & (df['LAUNCH_YEAR'] <= end)])
    pct = cnt / total_sats * 100
    label = f'{start}s' if end < 2029 else f'{start}s (partial)'
    html += f'''    <tr><td>{label}</td><td class="num">{cnt:,}</td><td class="num">{pct:.1f}%</td></tr>
'''

html += f'''  </table>
</section>

<!-- ═══════════ SECTION 5: ORBITAL PARAMETERS ═══════════ -->
<section id="orbital-characteristics">
  <h2>Orbital Parameter Deep Dive</h2>
  <p>This section examines the statistical distributions of the three core orbital parameters: <strong>inclination</strong>, <strong>eccentricity</strong>, and <strong>mean motion</strong>. These distributions reveal the most populated orbital shells and highlight outlier populations.</p>

  <h3>Inclination</h3>
  <p>The inclination distribution is bimodal: a large peak near <strong>53°</strong> (Starlink's shell) and another near <strong>97–98°</strong> (sun-synchronous orbits for Earth observation). The median across all satellites is <strong>{median_inclination:.1f}°</strong>.</p>

  <div class="chart-card">{img_tag(chart_inclination, 'Inclination Distribution')}</div>

  <h3>Eccentricity</h3>
  <p>The vast majority of active satellites operate in near-circular orbits. The distribution is heavily right-skewed, with most values below 0.01. A small but notable population of HEO satellites (e.g., Molniya orbits) occupies the tail above 0.5.</p>

  <div class="chart-card">{img_tag(chart_eccentricity, 'Eccentricity Distribution')}</div>

  <h3>Mean Motion</h3>
  <p>Mean motion distribution shows a dominant LEO peak (above {LEO_THRESHOLD} rev/day), a sparse MEO region (navigation satellites at ~2 rev/day and ~6.4 rev/day for some geodetic satellites), and a distinct GEO cluster at ~1.0 rev/day.</p>

  <div class="chart-card">{img_tag(chart_mean_motion, 'Mean Motion Distribution')}</div>

  <h3>Notable Orbital Outliers</h3>
  <table>
    <tr><th>Category</th><th>Filter</th><th class="num">Count</th><th class="num">Share (%)</th></tr>
'''

# Outlier categories
polar_sats = len(df[df['INCLINATION'] >= 89])
equatorial_sats = len(df[df['INCLINATION'] <= 5])
heo_sats = len(df[df['ECCENTRICITY'] > 0.1])
high_ecc_sats = len(df[df['ECCENTRICITY'] > 0.5])
retrograde_sats = len(df[df['INCLINATION'] > 90])

outliers = [
    ('Polar orbits (i &ge; 89°)', f'INCLINATION &ge; 89°', polar_sats),
    ('Near-equatorial (i &le; 5°)', f'INCLINATION &le; 5°', equatorial_sats),
    ('High eccentricity (e &gt; 0.1)', 'ECCENTRICITY &gt; 0.1', heo_sats),
    ('Very high eccentricity (e &gt; 0.5)', 'ECCENTRICITY &gt; 0.5', high_ecc_sats),
    ('Retrograde orbits (i &gt; 90°)', 'INCLINATION &gt; 90°', retrograde_sats),
]

for label, filt, cnt in outliers:
    pct = cnt / total_sats * 100
    html += f'''    <tr><td>{label}</td><td style="font-size:0.85rem;color:var(--text2)">{filt}</td><td class="num">{cnt:,}</td><td class="num">{pct:.1f}%</td></tr>
'''

html += f'''  </table>
</section>

<!-- ═══════════ SECTION 6: CONCLUSIONS ═══════════ -->
<section id="conclusions">
  <h2>Key Takeaways &amp; Outlook</h2>

  <div class="callout warning">
    <strong>1. LEO is the new bottleneck.</strong> With {leo_share:.1f}% of all active satellites in Low Earth Orbit, orbital congestion is concentrated in a narrow altitude band. Conjunction assessments, collision avoidance, and debris mitigation must prioritize the LEO regime.
  </div>

  <div class="callout">
    <strong>2. A single operator reshapes the environment.</strong> Starlink's {starlink_count:,} satellites ({starlink_share:.1f}% of the global fleet) skew inclination distributions toward 53° and inflate LEO occupancy. Policy frameworks for spectrum allocation and orbital slot management must account for mega-constellation dominance.
  </div>

  <div class="callout">
    <strong>3. The fleet is young and growing fast.</strong> {post_2020_share:.1f}% of active satellites were launched since 2020. Replacement cycles are shortening, and deorbiting compliance will increasingly determine the long-term debris population. Without reliable post-mission disposal, the current growth rate poses compounding collision risk.
  </div>

  <div class="callout">
    <strong>4. GEO remains strategically important but numerically small.</strong> Only {geo_count:,} satellites ({geo_count/total_sats*100:.1f}%) occupy the geostationary belt, but they carry disproportionate economic and strategic value in communications and weather monitoring. Slot coordination and interference management remain critical.
  </div>

  <div class="callout">
    <strong>5. HEO and MEO represent specialized niches.</strong> With {heo_count:,} HEO and {meo_count:,} MEO satellites, these regimes serve targeted missions (signals intelligence, navigation, scientific observation). Growth here is measured and unlikely to produce the congestion pressures seen in LEO.
  </div>
</section>

</div>

<footer>
  <div class="container">
    Active Satellites in Earth Orbit &mdash; 2026 Catalog Analysis<br>
    Data source: CelesTrak / NORAD TLE via Kaggle<br>
    Report generated on {pd.Timestamp.now().strftime('%Y-%m-%d')}
  </div>
</footer>

</body>
</html>
'''

# ── Write Output ───────────────────────────────────────────────────────
os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
with open(OUTPUT_PATH, 'w', encoding='utf-8') as f:
    f.write(html)

print(f'Report generated: {OUTPUT_PATH}')
print(f'Total satellites: {total_sats:,}')
print(f'LEO: {leo_count:,} ({leo_share:.1f}%)')
print(f'Starlink: {starlink_count:,} ({starlink_share:.1f}%)')
print(f'Median inclination: {median_inclination:.1f}°')
print(f'Post-2020: {post_2020_count:,} ({post_2020_share:.1f}%)')
print(f'GEO: {geo_count:,}, MEO: {meo_count:,}, HEO: {heo_count:,}')

