  <p>Mean motion distribution shows a dominant LEO peak (above {LEO_THRESHOLD} rev/day), a sparse MEO region (navigation satellites at ~2 rev/day and ~6.4 rev/day for some geodetic satellites), and a distinct GEO cluster at ~1.0 rev/day.</p>

  <div class="chart-card">{img_tag(chart_mean_motion, 'Mean Motion Distribution')}</div>

  <h3>Notable Orbital Outliers</h3>
  <table>
    <tr><th>Category</th><th>Filter</th><th class="num">Count</th><th class="num">Share (%)</th></tr>
'''

# Outlier categories
polar_sats = len(df[df['INCLINATION'] >= 89])
equatorial_sats = len(df[df['INCLINATION'] <= 5])
heo_sats = len(df[df['ECCENTRICITY'] > 0.1])
high_ecc_sats = len(df[df['ECCENTRICITY'] > 0.5])
retrograde_sats = len(df[df['INCLINATION'] > 90])

outliers = [
    ('Polar orbits (i &ge; 89°)', f'INCLINATION &ge; 89°', polar_sats),
    ('Near-equatorial (i &le; 5°)', f'INCLINATION &le; 5°', equatorial_sats),
    ('High eccentricity (e &gt; 0.1)', 'ECCENTRICITY &gt; 0.1', heo_sats),
    ('Very high eccentricity (e &gt; 0.5)', 'ECCENTRICITY &gt; 0.5', high_ecc_sats),
    ('Retrograde orbits (i &gt; 90°)', 'INCLINATION &gt; 90°', retrograde_sats),
]

for label, filt, cnt in outliers:
    pct = cnt / total_sats * 100
    html += f'''    <tr><td>{label}</td><td style="font-size:0.85rem;color:var(--text2)">{filt}</td><td class="num">{cnt:,}</td><td class="num">{pct:.1f}%</td></tr>
'''

html += f'''  </table>
</section>

